import{_ as a,o,c as e,ag as r}from"./chunks/framework.D2veAa-g.js";const b=JSON.parse('{"title":"操作系统概述","description":"","frontmatter":{"title":"操作系统概述"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/操作系统概述.md","filePath":"综合知识/系统基础/操作系统/操作系统概述.md","lastUpdated":null}'),d={name:"综合知识/系统基础/操作系统/操作系统概述.md"};function l(i,t,n,h,s,u){return o(),e("div",null,[...t[0]||(t[0]=[r('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 操作系统定义与作用</li><li>[ ] 四大特征与五大功能</li><li>[ ] 操作系统分类</li><li>[ ] 嵌入式操作系统</li><li>[ ] 网络操作系统</li><li>[ ] 内核特征</li><li>[ ] 软件分类（系统软件 vs 应用软件）</li><li>[ ] 系统监视</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="定义与作用" tabindex="-1">定义与作用 <a class="header-anchor" href="#定义与作用" aria-label="Permalink to &quot;定义与作用&quot;">​</a></h3><p><strong>定义</strong>：能有效地组织和管理系统中的各种软/硬件资源，合理地组织计算机系统工作流程，控制程序的执行，并向用户提供良好的工作环境和友好的接口。</p><p><strong>三个作用</strong>：</p><ul><li>管理计算机中运行的程序和分配各种软硬件资源</li><li>为用户提供友善的人机界面</li><li>为应用程序的开发和运行提供高效率的平台</li></ul><h3 id="四大特征与五大功能" tabindex="-1">四大特征与五大功能 <a class="header-anchor" href="#四大特征与五大功能" aria-label="Permalink to &quot;四大特征与五大功能&quot;">​</a></h3><p><strong>四个特征</strong>：并发性、共享性、虚拟性、不确定性</p><ul><li>并发 vs 并行：并发是宏观的（分时调度），并行是微观的</li></ul><p><strong>五大功能</strong>：</p><ul><li>进程管理 — 对 CPU 执行&quot;时间&quot;进行管理</li><li>文件管理 — 文件存储空间管理、目录管理、读写管理和存取控制</li><li>存储管理 — 对主存储器&quot;空间&quot;进行管理</li><li>设备管理 — 对硬件设备的管理，包括输入/输出设备的分配、启动、完成和回收</li><li>作业管理 — 任务、界面管理、人机交互等</li></ul><h3 id="操作系统分类" tabindex="-1">操作系统分类 <a class="header-anchor" href="#操作系统分类" aria-label="Permalink to &quot;操作系统分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td>批处理操作系统</td><td>单道/多道批处理（主机与外设可并行）</td></tr><tr><td>分时操作系统</td><td>CPU 时间划分为时间片，轮流为各终端服务</td></tr><tr><td>实时操作系统</td><td>在被控对象允许的时间范围内快速反应，可靠性要求高</td></tr><tr><td>网络操作系统</td><td>集中模式 / C/S 模式 / 对等模式</td></tr><tr><td>分布式操作系统</td><td>多台计算机无主次之分，通过通信交换信息</td></tr><tr><td>微机操作系统</td><td>Windows、Mac OS、Linux</td></tr></tbody></table><blockquote><p>⚠️ 多道批处理：允许多个作业同时装入内存，宏观并行微观串行。同一时刻可有多个作业在内存。</p></blockquote><h3 id="嵌入式操作系统" tabindex="-1">嵌入式操作系统 <a class="header-anchor" href="#嵌入式操作系统" aria-label="Permalink to &quot;嵌入式操作系统&quot;">​</a></h3><blockquote><p>🎯 一句话结论：嵌入式 OS 的特点是<strong>微型化、可定制、实时性、可靠性、易移植性</strong>。⚠️ 图形界面友好性<strong>不是</strong>主要特点。</p></blockquote><ul><li>易移植性：采用 HAL（硬件抽象层）和 BSP（板级支持包）设计</li><li>初始化过程（自底向上）：片级初始化 → 板级初始化 → 系统初始化</li></ul><h3 id="网络操作系统" tabindex="-1">网络操作系统 <a class="header-anchor" href="#网络操作系统" aria-label="Permalink to &quot;网络操作系统&quot;">​</a></h3><blockquote><p>🎯 一句话结论：硬件独立性指<strong>可运行在不同网络硬件上并能与其他网络连接</strong>，不依赖特定硬件平台。</p></blockquote><h3 id="内核特征" tabindex="-1">内核特征 <a class="header-anchor" href="#内核特征" aria-label="Permalink to &quot;内核特征&quot;">​</a></h3><blockquote><p>🎯 一句话结论：内核以 CPU 最高优先级运行、可执行特权指令、可直接访问全部主存空间。⚠️ 内核<strong>必须常驻内存</strong>。</p></blockquote><h3 id="软件分类" tabindex="-1">软件分类 <a class="header-anchor" href="#软件分类" aria-label="Permalink to &quot;软件分类&quot;">​</a></h3><blockquote><p>🎯 一句话结论：系统软件不依赖特定应用领域，应用软件为特定领域设计。</p></blockquote><table tabindex="0"><thead><tr><th>类型</th><th>定义</th><th>示例</th></tr></thead><tbody><tr><td>系统软件</td><td>控制和管理计算机资源，为应用软件提供运行服务，<strong>不依赖特定应用领域</strong></td><td>操作系统、编译程序、设备驱动</td></tr><tr><td>应用软件</td><td>为<strong>特定应用领域</strong>设计的软件</td><td>财务软件</td></tr></tbody></table><p>软件系统的完整构成 = <strong>程序 + 相关文档资料 + 数据的集合</strong>（不只是程序）。</p><h3 id="系统监视" tabindex="-1">系统监视 <a class="header-anchor" href="#系统监视" aria-label="Permalink to &quot;系统监视&quot;">​</a></h3><blockquote><p>🎯 一句话结论：系统监视三种方式 — ① 系统命令 ② 系统记录文件 ③ 监控工具（如 Windows Perfmon）。</p></blockquote><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>系统命令</td><td>直接执行系统命令查看状态</td><td>Linux <code>ps</code>、<code>last</code></td></tr><tr><td>系统记录文件</td><td>查阅系统日志</td><td><code>/var/log/</code></td></tr><tr><td>监控工具</td><td>集成命令、文件记录和可视化的监控工具</td><td>Windows <strong>Perfmon</strong></td></tr></tbody></table>',29)])])}const q=a(d,[["render",l]]);export{b as __pageData,q as default};
